q: queue.Queue[Record] = queue.Queue(maxsize=10_000)
def tap(rec: Record) -> None:
    try:
        q.put_nowait(rec)          # enqueue only; never write on the request path
    except queue.Full:
        DROPS.inc()                # explicit, monitored loss policy
def writer(db_path: str) -> None:
    con = sqlite3.connect(db_path, isolation_level=None)
    con.execute("PRAGMA journal_mode=WAL")     # readers do not block the writer
    while (rec := q.get()) is not None:
        with con:                  # BEGIN/COMMIT per record (or batched)
            con.execute("INSERT OR IGNORE INTO msg_store VALUES (?,?,?,?)",
                        (rec.id, rec.channel, rec.at, rec.body_json))
